#endif

// ------------------------------------------------------------------
// Tiled FP16 Conv2d forward (stride=4, padding=2, kernel=11)
// ------------------------------------------------------------------
template <int KSIZE, int STRIDE, int PAD>
__global__ void conv2d_fp16_tiled_kernel(
    const __half* __restrict__ input,   // [N, Cin, H, W]
    const __half* __restrict__ weight,  // [Cout, Cin, K, K]
    const __half* __restrict__ bias,    // [Cout] or nullptr
    __half* __restrict__ output,        // [N, Cout, Hout, Wout]
    const int N,
    const int Cin,
    const int H,
    const int W,
    const int Cout,
    const int Hout,
    const int Wout,
    const int tile_h,
    const int tile_w,
    const int shared_h,
    const int shared_w)
