    int batch_chan = blockIdx.z;
    int n = batch_chan / Cout;
    int c_out = batch_chan % Cout;

    // top‑left output pixel for this block
    int h_out_start = blockIdx.y * tile_h;
    int w_out_start = blockIdx.x * tile_w;

    // thread coordinates inside the tile
    int ty = threadIdx.y;   // 0 .. tile_h-1
    int tx = threadIdx.x;   // 0 .. tile_w-1

    // output indices for this thread
    int h_out = h_out_start + ty;
    int w_out = w_out_start + tx;

    // guard against out‑of‑bounds output
    if (h_out >= Hout || w_out >= Wout) return;

    // ------------------------------------------------------------------
    // Shared memory layout (dynamic):
    //   sh_input  : Cin * shared_h * shared_w
    //   sh_weight : Cin * KSIZE * KSIZE
    // ------------------------------------------------------------------
    extern __shared__ __half shmem[];
    __half* sh_input  = shmem;                                          // size Cin*shared_h*shared_w
    __half* sh_weight = shmem + Cin * shared_h * shared_w;               // size Cin*KSIZE*KSIZE

    // ------------------------------------------------------------------
    // Load weight for this output channel into shared memory
    // ------------------------------------------------------------------
    const int weight_elems = Cin * KSIZE * KSIZE;
    for (int idx = threadIdx.y * blockDim.x + threadIdx.x;
         idx < weight_elems;
         idx += blockDim.x * blockDim.y) {
        int c_in = idx / (KSIZE * KSIZE);
        int rem  = idx % (KSIZE * KSIZE);
        int kh   = rem / KSIZE;
        int kw   = rem % KSIZE;
        // weight layout: [Cout, Cin, K, K]
        int w_idx = ((c_out * Cin + c_in) * KSIZE + kh) * KSIZE + kw;
        sh_weight[idx] = weight[w_idx];
    }

    // ------------------------------------------------------------------
    // Load input tile (with padding) into shared memory
    // ------------------------------------------------------------------
    const int input_tile_elems = Cin * shared_h * shared_w;
    for (int idx = threadIdx.y * blockDim.x + threadIdx.x;
         idx < input_tile_elems;
         idx += blockDim.x * blockDim.y) {
        int c_in = idx / (shared_h * shared_w);
        int pos  = idx % (shared_h * shared_w);
        int ih   = pos / shared_w;   // 0 .. shared_h-1
        int iw   = pos % shared_w;   // 0 .. shared_w-1

        int h_in = h_out_start * STRIDE - PAD + ih;
        int w_in = w_out_start * STRIDE - PAD + iw;

        __half val = __float2half(0.0f);
        if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
            int in_idx = ((n * Cin + c_in) * H + h_in) * W + w_in;
            val = input[in_idx];
        }
        sh_input[idx] = val;
    }

    __syncthreads();

    // ------------------------------------------------------------------
    // Compute convolution for this output element
    // ------------------------------------------------------------------
    float acc = bias ? __half2float(bias[c_out]) : 0.0f;

    for (int c_in = 0; c_in < Cin; ++c_in) {
        for (int kh = 0; kh < KSIZE; ++kh) {
            int sh_ih = ty * STRIDE + kh;          // index inside shared input
            for (int kw = 0; kw < KSIZE; ++kw) {
                int sh_iw = tx * STRIDE + kw;      // index inside shared input
                int sh_idx = c_in * (shared_h * shared_w) + sh_ih * shared_w + sh_iw;
                int w_idx  = c_in * (KSIZE * KSIZE) + kh * KSIZE + kw; // index inside sh_weight
                float a = __half2float(sh_input[sh_idx]);
                float b = __half2float(sh_weight[w_idx]);
                acc += a * b;
            }
        }
    }

    int out_idx = ((n * Cout + c_out) * Hout + h_out) * Wout + w_out;
    output[out_idx] = __float2half_rn(acc);
}

// ------------------------------------------------------------------
// Host wrapper
// ------------------------------------------------------------------
torch::Tensor conv2d_fp16_forward(torch::Tensor input,
                                  torch::Tensor weight,
                                  torch::Tensor bias) {
    CHECK_INPUT(input);
    CHECK_INPUT(weight);
    if (bias.defined()) CHECK_INPUT(bias);

    const int N   = input.size(0);
    const int Cin = input.size(1);
    const int H   = input.size(2);
    const int W   = input.size(3);

    const int Cout = weight.size(0);
    const int K    = weight.size(2); // assume square kernel

    const int stride = 4;
    const int padding = 2;

    const int Hout = static_cast<int>(std::floor((H + 2 * padding - (K - 1) - 1) / static_cast<float>(stride) + 1));
    const int Wout = static_cast<int>(std::floor((W + 2 * padding - (K - 1) - 1) / static_cast<float>(stride) + 1));

    auto output = torch::empty({N, Cout, Hout, Wout}, input.options());

    // Tile configuration (chosen for the given kernel/stride)
    const int tile_h = 8;
    const int tile_w = 8;
    const int shared_h = tile_h * stride + K - stride; // = 8*4 + 11 - 4 = 39
    const int shared_w = tile_w * stride + K - stride; // = 39

    const dim3 block(tile_w, tile_h);
    const dim3 grid((Wout + tile_w - 1) / tile_w,
                    (Hout + tile_h - 1) / tile_h,
                    N * Cout);

    size_t shmem_bytes = (Cin * shared_h * shared_w + Cin * K * K) * sizeof(__half);

    // The reference uses K=11, stride=4, padding=2
    AT_ASSERTM(K == 11, "Only kernel size 11 is supported by this custom kernel");
    conv2d_fp16_tiled_kernel<11, 4, 2><<<grid, block, shmem_bytes>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        bias.defined() ? reinterpret_cast<const __half*>(bias.data_ptr<at::Half>()) : nullptr,
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N, Cin, H, W, Cout, Hout, Wout,
        tile_h, tile_w, shared_h, shared_w);

    cudaDeviceSynchronize();
    return output;
}
"""

